cmd:
echo ${z:-$(bash <<'E O F'
cargo test --all
E O F
)}

echo "$( # c)
bash <<'EOF'
cargo test --all
EOF
)"

echo "$( # c)
sh <<"EOF"
cargo test --all
EOF
)"

echo "$( # c)
bash -s <<-EOF
	cargo test --all
	EOF
)"

echo "$( # c)
source /dev/stdin <<'EOF'
cargo test --all
EOF
)"

echo "$( # c)
bash /dev/stdin <<'EOF'
cargo test --all
EOF
)"

echo "$( # c)
bash -c 'cat | bash' <<'EOF'
cargo test --all
EOF
)"

echo "$( # c)
cat <<'EOF'
cargo test --all
EOF
)"

echo "$( # c)
bash <<'E O F'
cargo test --all
E O F
)"

echo "$( # c)
bash <<'END'
cargo test --all
END
)"
